'use strict';
(() => {
  const q=s=>document.querySelector(s),key='bonga-visibility-v1';let state={prospects:[],backlinks:[]};
  try{const data=JSON.parse(localStorage.getItem(key)||'{}');if(Array.isArray(data.prospects))state.prospects=data.prospects.slice(0,100);if(Array.isArray(data.backlinks))state.backlinks=data.backlinks.slice(0,100);}catch{}
  const url=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
  function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{q('#research-status').textContent='Storage unavailable. Export your records before closing.';}}
  function evidence(href,label){const a=document.createElement('a');a.href=href;a.textContent=label;a.target='_blank';a.rel='noopener noreferrer';return a;}
  function render(){
    q('#prospect-results').replaceChildren();q('#backlink-results').replaceChildren();
    if(!state.prospects.length)q('#prospect-results').textContent='No business records imported yet.';
    for(const p of state.prospects){const card=document.createElement('article');card.className='research-row';const title=document.createElement('h4');title.textContent=p.name;const details=document.createElement('p');details.textContent=[p.address,p.phone].filter(Boolean).join(' · ');const date=document.createElement('small');date.textContent='Needs review · '+(p.checked_at||'Check date unavailable');card.append(title,details,evidence(p.source_url,'Review source'),date);if(p.website)card.append(evidence(p.website,'Business website'));const button=document.createElement('button');button.type='button';button.className='button secondary';button.textContent='Add to my customer pipeline';button.addEventListener('click',()=>{q('#lead-name').value=p.name;q('#lead-service').value='Fashion & garments';q('#lead-next').value='Review fit and prepare a relevant fashion offer';q('#lead-form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));q('#pipeline-title').scrollIntoView({behavior:'smooth'});});card.append(button);q('#prospect-results').append(card);}
    if(!state.backlinks.length)q('#backlink-results').textContent='No link checks imported yet.';
    for(const p of state.backlinks){const row=document.createElement('article');row.className='research-row';const status=document.createElement('strong');status.textContent=p.status==='found'?'Link found':p.status==='missing'?'Link not found on this page':'Could not verify';const date=document.createElement('small');date.textContent=p.checked_at||'Check date unavailable';row.append(status,evidence(p.source_url,'Review checked page'),date);q('#backlink-results').append(row);}
  }
  q('#research-import').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>2_000_000)throw Error('Use a file smaller than 2 MB.');const data=JSON.parse(await file.text());let count=0;
    for(const p of (Array.isArray(data.prospects)?data.prospects:[]).slice(0,100)){if(typeof p.name!=='string'||!p.name.trim()||!url(p.source_url))continue;const record={name:p.name.slice(0,150),source_url:url(p.source_url),website:url(p.website),address:String(p.address||'').slice(0,300),phone:String(p.phone||'').slice(0,80),checked_at:String(p.checked_at||'').slice(0,50)};if(state.prospects.some(x=>x.source_url===record.source_url))continue;state.prospects.push(record);count++;}
    for(const p of (Array.isArray(data.backlinks)?data.backlinks:[]).slice(0,100)){if(!url(p.source_url)||!url(p.target_url)||!['found','missing','blocked','error','unsupported','too_large'].includes(p.status))continue;state.backlinks=state.backlinks.filter(x=>x.source_url!==url(p.source_url)||x.target_url!==url(p.target_url));state.backlinks.push({source_url:url(p.source_url),target_url:url(p.target_url),status:p.status,checked_at:String(p.checked_at||'').slice(0,50)});count++;}
    if(!count)throw Error('No new usable records found. Choose an evidence results file.');state.prospects=state.prospects.slice(-100);state.backlinks=state.backlinks.slice(-100);save();render();q('#research-status').textContent=count+' records imported for review.';
  }catch(error){q('#research-status').textContent=error.message;}event.target.value='';});
  q('#research-export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Bonga-visibility-records.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);});render();
})();
